async:
try (var executor = java.util.concurrent.Executors.newFixedThreadPool(1)) {
 assertEquals(6, AsyncTotals.doubled(3, executor).get(2, java.util.concurrent.TimeUnit.SECONDS));
 var error = assertThrows(java.util.concurrent.ExecutionException.class, () -> AsyncTotals.doubled(-1, executor).get(2, java.util.concurrent.TimeUnit.SECONDS));
 assertInstanceOf(IllegalArgumentException.class, error.getCause());
}
